import{_ as n,o as t,c as a,a3 as i}from"./chunks/framework.BlfGB29P.js";const p=JSON.parse('{"title":"Blocks JS","description":"","frontmatter":{},"headers":[],"relativePath":"projects/logic-studio/user-guide/blocks-js.md","filePath":"projects/logic-studio/user-guide/blocks-js.md","lastUpdated":1794767190000}'),r={name:"projects/logic-studio/user-guide/blocks-js.md"};function o(s,e,l,d,u,h){return t(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="blocks-js" tabindex="-1">Blocks JS <a class="header-anchor" href="#blocks-js" aria-label="Permalink to &quot;Blocks JS&quot;">​</a></h1><h2 id="erstes-beispiel" tabindex="-1">Erstes Beispiel <a class="header-anchor" href="#erstes-beispiel" aria-label="Permalink to &quot;Erstes Beispiel&quot;">​</a></h2><p>Ziehe einen Block für die Protokollausgabe in den Arbeitsbereich. Verbinde seinen Werteingang mit <strong>Zustand von Entität</strong> und wähle deinen Testhelfer. Starte den Testlauf und suche den Wert im Protokoll.</p><h2 id="funktionen" tabindex="-1">Funktionen <a class="header-anchor" href="#funktionen" aria-label="Permalink to &quot;Funktionen&quot;">​</a></h2><h3 id="system-aktionen-und-sendto" tabindex="-1">System, Aktionen und Sendto <a class="header-anchor" href="#system-aktionen-und-sendto" aria-label="Permalink to &quot;System, Aktionen und Sendto&quot;">​</a></h3><p>Lies Entitäten, schalte freigegebene Ziele, sende Nachrichten oder nutze eine Verlaufsabfrage. Dynamische Anschlüsse nehmen zum Beispiel eine Entitäts-ID aus einer Schleife an.</p><h3 id="trigger-datum-und-timeouts" tabindex="-1">Trigger, Datum und Timeouts <a class="header-anchor" href="#trigger-datum-und-timeouts" aria-label="Permalink to &quot;Trigger, Datum und Timeouts&quot;">​</a></h3><p>Starte Aktionen bei Zustandsänderung, Astrozeit oder Zeitplan. Nutze einfache oder benannte CRON-Pläne, Verzögerungen und Intervalle. Benannte Läufe lassen sich stoppen.</p><h3 id="werte-bearbeiten" tabindex="-1">Werte bearbeiten <a class="header-anchor" href="#werte-bearbeiten" aria-label="Permalink to &quot;Werte bearbeiten&quot;">​</a></h3><p>Konvertierung, Objekt, Logik, Mathematik, Text, Listen und Farbe liefern Werte, die du in andere Blöcke stecken kannst. Schleifen wiederholen Abläufe.</p><h3 id="variablen-und-funktionen" tabindex="-1">Variablen und Funktionen <a class="header-anchor" href="#variablen-und-funktionen" aria-label="Permalink to &quot;Variablen und Funktionen&quot;">​</a></h3><p>Speichere Zwischenwerte in Variablen. Funktionen bündeln Schritte, können Werte zurückgeben und lassen sich erneut aufrufen.</p><h3 id="iobroker-import" tabindex="-1">ioBroker-Import <a class="header-anchor" href="#iobroker-import" aria-label="Permalink to &quot;ioBroker-Import&quot;">​</a></h3><p>Öffne im Expertenmodus <strong>ioBroker-Export einfügen</strong>, füge den Export ein und prüfe die Übersicht. Wähle HA-Entitäten ausdrücklich zu und beachte Hinweise direkt am Block.</p><h3 id="http-in-importierten-blocken" tabindex="-1">HTTP in importierten Blöcken <a class="header-anchor" href="#http-in-importierten-blocken" aria-label="Permalink to &quot;HTTP in importierten Blöcken&quot;">​</a></h3><p>Ordne einen freigegebenen HA-REST-Befehl zu. URL, Timeout und zusätzliche Request-Header werden in HA konfiguriert. Der importierte Content-Type steht als Vorgabe im POST-Block.</p><h3 id="testlauf-und-play" tabindex="-1">Testlauf und Play <a class="header-anchor" href="#testlauf-und-play" aria-label="Permalink to &quot;Testlauf und Play&quot;">​</a></h3><p>Der Testlauf simuliert. Speichere vor Play und schau im Protokoll nach, ob die echte HA-Aktion ausgeführt wurde.</p><h2 id="wenn-etwas-nicht-klappt" tabindex="-1">Wenn etwas nicht klappt <a class="header-anchor" href="#wenn-etwas-nicht-klappt" aria-label="Permalink to &quot;Wenn etwas nicht klappt&quot;">​</a></h2><p>Wenn der Import einen Platzhalter zeigt, lies den Blockhinweis und ersetze oder ergänze den Block vor dem Start.</p>',20)])])}const k=n(r,[["render",o]]);export{p as __pageData,k as default};
